    const rows=occurrences.sort((a,b)=>a.date.localeCompare(b.date)||String(a.p.role||'').localeCompare(String(b.p.role||''),'pt-BR')).map(x=>`<tr><td><b>${br(x.date)}</b><small>${DAY_NAMES[dateObj(x.date).getDay()]}</small></td><td><b>${esc(x.p.personName)}</b><small>${esc(x.p.role||'Sem função')}</small></td><td><b>${esc(actionLabel(x.p))}</b><small>${esc(x.timing.instruction)}</small></td><td><b>${esc(x.timing.target)}</b><small>Base ${esc(x.timing.base)}</small></td><td>${x.support?`<b>${esc(x.support.nome)}</b><small>${esc(x.support.funcao||'Apoio')}</small>`:'<span class="fsBHNoWeeklySupport">Não se aplica</span>'}</td><td><span class="fsBHWeeklyStatus ${/^Aprovado|Comunicado|Cumprido/i.test(x.p.status||'')?'ok':'wait'}">${esc(x.p.status||'Pendente')}</span></td></tr>`).join('');
